	\begin{equation}\label{eq:CF}
		{\sum}{}^{\displaystyle\prime}w^{(m)}(\pi_{1}),
	\end{equation}
	where the sum is over multi-chains $\pi_{1}\dref\pi_{2}\dref\cdots\dref\pi_{l}$ of $m$-divisible non-crossing partitions in $\NC_{n;t}^{(m)}$, where the rank of $\pi_{i}$ is $s'_{2}+s_{3}+\cdots+s_{i}$, for $i\in\{2,3,\ldots,l\}$, is given by
	\begin{multline}\label{eq:CG}
		\frac{t(mn-t+1)-s_{l+1}(t-1)}{mn-t+1}\binom{mn}{s_{3}}\cdots\binom{mn}{s_{l}}\binom{mn-t+1}{s_{l+1}}\\
		\times\sum_{k=0}^{s_{3}+\cdots+s_{l+1}+t-1}{\frac{1}{mn+k+1}(-1)^{k+s_{3}+\cdots+s_{l+1}+t-1}\binom{s_{3}+\cdots+s_{l+1}+t-1}{k}}\\
		\cdot\coef{z^{0}}z^{k+1}F(z)^{-mn-k-1}.
	\end{multline}
	If $l=2$, the empty product $\binom{mn}{s_{3}}\cdots\binom{mn}{s_{l}}$ of binomial coefficients has to be interpreted as $1$.
\end{prop}

